请对以下 case 进行三维加权评分。

=== case_id ===
Case-23-countdown-013

=== 用户原始指令 (query.txt) ===
结婚纪念日倒计时卡片,中间环形显示"距离纪念日30天",下面一排横向小图标(心形、戒指、蛋糕),氛围从背景延伸出来,中间一个明显按钮写着"查看纪念日",点进去看日历里那个纪念日事件。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "结婚纪念日倒计时卡片,中间环形显示\"距离纪念日30天\",下面一排横向小图标(心形、戒指、蛋糕),氛围从背景延伸出来,中间一个明显按钮写着\"查看纪念日\",点进去看日历里那个纪念日事件。",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToIntent",
      "args": {
        "intentName": "ViewCalendarEvent",
        "params": {
          "entityId": "anniv-2026-001"
        }
      }
    }
  ],
  "dataModelSchema": {
    "view": {
      "ringCaption": {
        "type": "string",
        "description": "环形主视觉内的倒计时说明文案。",
        "sampleValue": "距离纪念日"
      },
      "daysRemainingText": {
        "type": "string",
        "description": "距离结婚纪念日的剩余天数展示文本。",
        "sampleValue": "30天"
      },
      "progressValue": {
        "type": "number",
        "description": "环形倒计时进度当前值，用于形成仪表视觉。",
        "sampleValue": 70
      },
      "progressTotal": {
        "type": "number",
        "description": "环形倒计时进度总量。",
        "sampleValue": 100
      },
      "actionLabel": {
        "type": "string",
        "description": "查看结婚纪念日日历事件的入口文案。",
        "sampleValue": "查看纪念日"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "结婚纪念日事件在本地日历中的唯一标识符。",
              "sampleValue": "anniv-2026-001"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/heart_fill.svg",
      "description": "黑色心形实心图标，适合表达结婚纪念日和亲密关系的情感符号。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "黑色日历实心图标，适合表达纪念日事件和日历查看入口。"
    },
    {
      "src": "resources/base/media/stopwatch_fill.svg",
      "description": "黑白秒表实心图标，适合表达倒计时和时间临近。"
    }
  ]
}

